object Solution {
    def numTriplets(nums1: Array[Int], nums2: Array[Int]): Int = {
        import scala.collection.mutable

        def countTriplets(arr1: Array[Int], arr2: Array[Int]): Int = {
            // Count product frequencies of pairs in arr2
            val productCount = mutable.Map[Long, Int]()
            val n = arr2.length
            for {
                i <- 0 until n
                j <- i + 1 until n
            } {
                val prod = arr2(i).toLong * arr2(j).toLong
                productCount(prod) = productCount.getOrElse(prod, 0) + 1
            }

            var res = 0
            for (x <- arr1) {
                val sq = x.toLong * x.toLong
                res += productCount.getOrElse(sq, 0)
            }
            res
        }

        countTriplets(nums1, nums2) + countTriplets(nums2, nums1)
    }
}

